    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] data = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            data[i] = (long) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        int[][] ranges = new int[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken(); ranges[i][0] = (int) in.nval;
            in.nextToken(); ranges[i][1] = (int) in.nval;
        }
        long[] ans = negateRanges(data, ranges);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i]).append(i + 1 < ans.length ? " " : "\n");
        System.out.print(sb);
    }
}
